import { generateStar } from '../generators/star.js';

/**
 * How fast the simulated table draws, in table radii per second.
 *
 * **A placeholder.** The real speed depends on mechanics that are not chosen.
 * It exists so that every design's estimated duration comes from its length by
 * the same rule, instead of from four unrelated guesses.
 */
export const NOMINAL_SPEED_RADII_PER_SECOND = 0.06;

/** Durations are rounded to this many seconds, since they are only estimates. */
const DURATION_ROUNDING_SECONDS = 30;

/** Estimated drawing time for a trajectory, from the nominal speed. */
export function estimateDurationSeconds(trajectory: Trajectory): number {
  const seconds = trajectoryLength(trajectory) / NOMINAL_SPEED_RADII_PER_SECOND;

  return Math.max(
    DURATION_ROUNDING_SECONDS,
    Math.round(seconds / DURATION_ROUNDING_SECONDS) * DURATION_ROUNDING_SECONDS,
  );
}

